<script setup lang="ts">
import { formatAdminDate } from "~/utils/format-date"
const PAGE_SIZE=25;const offset=ref(0);const tenantId=ref("");const capability=ref("");const data=ref<any>();const error=ref("");
async function refresh(){error.value="";try{data.value=await $fetch('/api/provider/activity',{query:{tenantId:tenantId.value||undefined,capability:capability.value||undefined,offset:offset.value,limit:PAGE_SIZE}})}catch(e:any){error.value=e?.data?.message??e?.statusMessage??e?.message}}
watch(offset,refresh);watch([tenantId,capability],()=>{offset.value=0});await refresh()
</script><template><div class="page-stack"><div class="page-heading"><div><p class="eyebrow">ACTIVITY</p><h1>IAM Activity</h1><p>Provider-safe activity from canonical IAM events.</p></div><button class="secondary-button" @click="refresh">Refresh</button></div><section class="panel"><div class="admin-filters"><input v-model="tenantId" placeholder="Tenant ID (optional)"><select v-model="capability"><option value="">All capabilities</option><option value="identity">Identity</option><option value="membership">Membership</option><option value="access">Access</option></select><button class="secondary-button" @click="offset=0;refresh()">Apply</button></div><div v-if="error" class="alert alert--error">{{error}}</div><div v-else-if="data" class="table-wrap"><table><thead><tr><th>Occurred</th><th>Capability</th><th>Event</th><th>Resource</th><th>Actor</th><th>Tenant</th><th>Correlation</th></tr></thead><tbody><tr v-for="item in data.items" :key="item.activityId"><td>{{formatAdminDate(item.occurredAt)}}</td><td>{{item.capability}}</td><td>{{item.eventType}}</td><td class="mono">{{item.resource?.id}}</td><td class="mono">{{item.actorId??'—'}}</td><td class="mono">{{item.tenantId??'—'}}</td><td class="mono">{{item.correlationId??'—'}}</td></tr></tbody></table></div><AppPagination v-if="data" :total="data.total??0" :offset="offset" :limit="PAGE_SIZE" @change="offset=$event" /></section></div></template>